using System;using UnityEngine;using UnityEngine.InputSystem;using TMPro;
namespace CrossTheLine {
public sealed class TempleCleansing:MonoBehaviour {
 public int Stage{get;private set;}public int ClearedCount{get;private set;}public bool WhipMade{get;private set;}public bool IsCinematic=>crafting||clearing>=0;public Transform Player=>player;public Vector3 StallPosition(int i)=>new Vector3(-5+i*5,-1.8f,0);
 JourneyGame game;Transform player,whip;SpriteRenderer playerBody;Material mat;Sprite square;GameObject environment;Transform[] merchants=new Transform[6],tables=new Transform[3],animals=new Transform[4],coins=new Transform[12];bool[] cleared=new bool[3];bool crafting,busy,instructed,shutdown,oldPixel;int clearing=-1;float clock;Vector3 target;UnityEngine.Rendering.Universal.PixelPerfectCamera pixel;
 public void Initialize(JourneyGame g,Transform p,SpriteRenderer body,Material m,Sprite s,int step){JourneyObjectFactory.BeginStage(this,step);game=g;player=p;playerBody=body;mat=m;square=s;pixel=g.journeyCamera.GetComponent<UnityEngine.Rendering.Universal.PixelPerfectCamera>();if(pixel){oldPixel=pixel.enabled;pixel.enabled=false;}ConfigureStep(step);}
 Color C(string h){ColorUtility.TryParseHtmlString("#"+h,out var c);return c;}
 Transform Shape(string name,Transform parent,Vector3 pos,Vector2 size,string color,int order){var o=JourneyObjectFactory.Create(name);o.transform.SetParent(parent,false);o.transform.localPosition=pos;o.transform.localScale=new Vector3(size.x,size.y,1);var r=o.GetOrAddComponent<SpriteRenderer>();r.sprite=square;r.sharedMaterial=mat;r.color=C(color);r.sortingOrder=order;return o.transform;}
 Transform Shape(string n,float x,float y,float w,float h,string color,int order=0)=>Shape(n,environment.transform,new Vector3(x,y,0),new Vector2(w,h),color,order);
 Transform Actor(string name,Sprite sprite,float x,float y){var o=JourneyObjectFactory.Create(name);o.transform.SetParent(environment.transform,false);o.transform.position=JourneyStageLayout.Point(this,o.transform,"Placement 1",new Vector3(x,y,0));var r=JourneyObjectFactory.Create("Sprite").GetOrAddComponent<SpriteRenderer>();r.transform.SetParent(o.transform,false);r.sprite=sprite;r.sharedMaterial=mat;r.sortingOrder=40;float scale=1.6f/sprite.bounds.size.y;r.transform.localScale=Vector3.one*scale;r.transform.localPosition=new Vector3(-JourneySpriteAssets.VisibleBounds(sprite).center.x*scale,-JourneySpriteAssets.VisibleBounds(sprite).min.y*scale,0);return o.transform;}
 void Label(string text,float x,float y){var o=JourneyObjectFactory.Create(text);o.transform.SetParent(environment.transform,false);o.transform.position=JourneyStageLayout.Point(this,o.transform,"Placement 2",new Vector3(x,y,0));var t=o.GetOrAddComponent<TextMeshPro>();t.font=game.koreanFont;t.text=text;t.fontSize=2.8f;t.color=C("56483a");t.alignment=TextAlignmentOptions.Center;t.GetComponent<RectTransform>().sizeDelta=new Vector2(8,1);t.GetComponent<MeshRenderer>().sortingOrder=70;}
 Transform Animal(string name,float x,float y,bool cow){var o=JourneyObjectFactory.Create(name);o.transform.SetParent(environment.transform,false);o.transform.position=JourneyStageLayout.Point(this,o.transform,"Placement 3",new Vector3(x,y,0));string color=cow?"98745a":"ded4bf";Shape("몸",o.transform,new Vector3(0,.4f,0),new Vector2(cow?1.2f:.85f,.55f),color,30);Shape("머리",o.transform,new Vector3(.6f,.65f,0),new Vector2(.35f,.4f),color,31);for(int i=0;i<4;i++)Shape("다리",o.transform,new Vector3(-.4f+i*.25f,.05f,0),new Vector2(.09f,.45f),"635549",29);Shape("뿔",o.transform,new Vector3(.65f,.95f,0),new Vector2(.1f,.2f),"e9dfc9",32);return o.transform;}
 public void ConfigureStep(int step){JourneyObjectFactory.BeginStage(this,step);Stage=Mathf.Min(step,4);busy=false;crafting=false;clearing=-1;instructed=false;clock=0;ClearedCount=Stage>=4?3:0;WhipMade=Stage>=3;Array.Clear(cleared,0,3);if(environment)Destroy(environment);environment=JourneyObjectFactory.Create("TempleCourtyard");environment.transform.SetParent(transform,false);Shape("성전 돌바닥",0,0,30,18,"d2c6a7",-10);Shape("성전 벽",0,3.5f,24,3,"e8dbc0",-8);Shape("성전 처마",0,3.9f,22,.6f,"b99e78",-6);for(int i=0;i<7;i++){float x=-9+i*3;Shape("성전 기둥",x,1.7f,.55f,3.7f,"efe4cb",-5);Shape("기둥 머리",x,3.45f,.95f,.25f,"c6b392",-4);}Shape("성전 출입문",-8.5f,-1.5f,1.9f,3.8f,"8d7a60",-3);Label("유월절 · 예루살렘 성전",0,3.2f);Label("출구 ←",-8,-3.7f);
 for(int i=0;i<3;i++){float x=-5+i*5;tables[i]=Shape("장사하는 상 "+i,x,-.15f,2.65f,.6f,"86603c",20);Shape("상 위",tables[i],new Vector3(0,.4f,0),new Vector2(1.05f,.22f),"b58c59",21);merchants[i*2]=Actor("상인 "+i,game.supportingCast[5],x-.7f,.5f);merchants[i*2+1]=Actor("손님 "+i,game.supportingCast[6],x+1,.45f);Label(i==0?"양과 소":i==1?"돈 바꾸는 상":"비둘기 장사",x,2.5f);if(Stage>=4){merchants[i*2].gameObject.SetActive(false);merchants[i*2+1].gameObject.SetActive(false);tables[i].rotation=Quaternion.Euler(0,0,-35);}}
 animals[0]=Animal("양",-6,-1.15f,false);animals[1]=Animal("소",-4.5f,-1.15f,true);for(int i=2;i<4;i++){animals[i]=Shape("비둘기",4.5f+(i-2)*1.1f,.25f,.25f,.17f,"f0e8d8",28);Shape("새 날개",animals[i],new Vector3(0,.5f,0),new Vector2(1.4f,.45f),"d7d1c6",29);}for(int i=0;i<12;i++)coins[i]=Shape("환전상 동전 "+i,-1.1f+i%4*.55f,.1f+i/4*.18f,.13f,.09f,"cfa750",30);if(Stage>=4){foreach(var a in animals)a.gameObject.SetActive(false);}
 Actor("베드로",game.disciples[0],-2,-3.5f);Actor("안드레",game.disciples[1],-.5f,-3.5f);Actor("빌립",game.disciples[4],1,-3.5f);var rope=JourneyObjectFactory.Create("노끈으로 만든 채찍");rope.transform.SetParent(environment.transform,false);whip=rope.transform;for(int i=0;i<9;i++)Shape("노끈 "+i,whip,new Vector3(i*.13f,Mathf.Sin(i*.6f)*.1f,0),new Vector2(.18f,.045f),"82603c",65);whip.gameObject.SetActive(Stage>=2);
 if(Stage==0){player.position=JourneyStageLayout.Point(this,player,"Placement 4",new Vector3(-7,-3.5f,0));target=new Vector3(-7.8f,-1.7f,0);}else {player.position=JourneyStageLayout.Point(this,player,"Placement 5",new Vector3(-2,-1.8f,0));target=Stage==1?new Vector3(0,-1.8f,0):Stage==2?new Vector3(-3,-2.2f,0):Stage==3?StallPosition(0):new Vector3(0,-1.8f,0);}game.journeyCamera.orthographicSize=5.625f;UpdateCamera();game.BaptismCinema(false);Hud();}
 void Hud(){string[] goals={"성전 입구로 들어가기","시장처럼 변한 성전 살펴보기","노끈으로 채찍 만들기","상인들을 출구로 내보내기 · "+ClearedCount+" / 3","조용해진 성전에서 제자들과 이야기하기"};game.TempleHud(goals[Stage],Stage==3?"장사하는 상 앞으로 이동 · E로 내보내기":"WASD / 방향키 · 이동    가까이에서 E · 이야기");}
 public void Tick(float dt,bool canMove,bool press){whip.position=player.position+new Vector3(.5f,.9f,0);if(crafting){clock+=dt;whip.rotation=Quaternion.Euler(0,0,Mathf.Sin(clock*7)*20);if(clock>=2){crafting=false;WhipMade=true;game.BaptismCinema(false);game.BaptismAdvance();}return;}if(clearing>=0){clock+=dt;whip.rotation=Quaternion.Euler(0,0,Mathf.Sin(clock*8)*70);playerBody.transform.localRotation=Quaternion.Euler(0,0,Mathf.Sin(clock*8)*6);tables[clearing].rotation=Quaternion.Euler(0,0,-Mathf.Clamp01(clock)*65);for(int j=0;j<2;j++){var m=merchants[clearing*2+j];m.position=Vector3.MoveTowards(m.position,new Vector3(-12,-2+j*.5f,0),dt*6);m.GetChild(0).GetComponent<SpriteRenderer>().flipX=true;}if(clearing==0)for(int i=0;i<2;i++)animals[i].position=Vector3.MoveTowards(animals[i].position,new Vector3(-12,-2,0),dt*6);if(clearing==1)for(int i=0;i<12;i++)coins[i].position=JourneyStageLayout.Point(this,coins[i],"Placement 6",new Vector3((i%4-1.5f)*.65f,-.3f-Mathf.Clamp01(clock)*(1+i/4*.3f)+Mathf.Abs(Mathf.Sin(clock*5+i))*.2f,0));if(clearing==2)for(int i=2;i<4;i++)animals[i].position+=new Vector3(-dt*4,dt*1.5f,0);if(clock>=3){foreach(var m in new[]{merchants[clearing*2],merchants[clearing*2+1]})m.gameObject.SetActive(false);cleared[clearing]=true;ClearedCount++;clearing=-1;playerBody.transform.localRotation=Quaternion.identity;whip.rotation=Quaternion.identity;game.BaptismCinema(false);Hud();if(ClearedCount==3)game.BaptismAdvance();}return;}if(!canMove||busy)return;var k=Keyboard.current;Vector2 v=Vector2.zero;if(k!=null){v.x=(k.dKey.isPressed||k.rightArrowKey.isPressed?1:0)-(k.aKey.isPressed||k.leftArrowKey.isPressed?1:0);v.y=(k.wKey.isPressed||k.upArrowKey.isPressed?1:0)-(k.sKey.isPressed||k.downArrowKey.isPressed?1:0);}var p=player.position+(Vector3)(v.normalized*3.6f*dt);p.x=Mathf.Clamp(p.x,-8.7f,8.7f);p.y=Mathf.Clamp(p.y,-3.6f,-1.1f);player.position=p;game.MeetingWalk(v.sqrMagnitude>0,v.x);Hud();if(press)Interact();}
 void BeginClear(int i){clearing=i;clock=0;game.BaptismCinema(true);}
 public void Interact(){if(busy||IsCinematic)return;if(Stage==3){for(int i=0;i<3;i++)if(!cleared[i]&&Vector3.Distance(player.position,StallPosition(i))<1.5f){if(!instructed){busy=true;int selected=i;game.MeetingTalk(()=>{busy=false;instructed=true;BeginClear(selected);});}else BeginClear(i);return;}return;}if(Vector3.Distance(player.position,target)>1.6f)return;busy=true;game.MeetingTalk(()=>{busy=false;if(Stage==2){crafting=true;clock=0;game.BaptismCinema(true);}else game.BaptismAdvance();});}
 public void UpdateCamera(){game.journeyCamera.transform.position=JourneyStageLayout.Point(this,game.journeyCamera.transform,"Placement 7",new Vector3(0,0,-10));}
 public void Shutdown(){if(shutdown)return;shutdown=true;if(pixel)pixel.enabled=oldPixel;}
 void OnDestroy(){Shutdown();}
}
